def I(name, qty='', unit=''):
    return {'name': name, 'qty': str(qty), 'unit': unit}


def R(title, cat, brand, ings, steps=(), summary='', notes='', video=''):
    return {'title': title, 'category': cat, 'brand': brand, 'summary': summary,
            'ingredients': ings, 'steps': list(steps), 'notes': notes, 'video': video}


