# ---------------- حفظ + ربط المقاطع ----------------
try:
    vids = json.load(urllib.request.urlopen('http://localhost:5173/api/videos'))
except Exception:
    vids = []


def vid(name):
    for v in vids:
        if v['file'].endswith('/' + name) or v['file'] == name:
            return v['id']
    return ''


out = []
for r in recipes:
    out.append({
        'id': uuid.uuid4().hex[:8], 'title': r['title'], 'category': r['category'], 'brand': r['brand'], 'summary': r['summary'],
        'ingredients': [i for i in r['ingredients'] if i['name']], 'steps': r['steps'], 'notes': r['notes'], 'video': vid(r['video']) if r['video'] else '',
    })
os.makedirs(os.path.dirname(OUT), exist_ok=True)
with open(OUT, 'w', encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=2)
print(len(out), 'ريسيبي،', sum(1 for r in out if r['video']), 'مرتبطة بمقاطع')
